# Compiler repair affects only this old fixed-offset historical input.
# All other current-source tests continue to use read() above.
def compiler_historical_read(path):
    from Tests.ContractChecks import test_profile_read_failure_remote_admission as admission
    data=(ROOT/'tools/run138_editor_readiness_contract.json').read_bytes()
    admission._combined_profile_contract(data,ROOT)
    value=(ROOT/path).read_bytes()
    if path==admission.MERCHANT_BUSINESS_COMPILE_PATH:
        hunk=admission.MERCHANT_BUSINESS_COMPILE_HUNK
        after=hunk['after'].encode();before=hunk['before'].encode()
        if value.count(after)!=1:raise ValueError('Missing unique merchant compiler span')
        value=value.replace(after,before,1)
        if hashlib.sha256(value).hexdigest()!=admission.MERCHANT_BUSINESS_PRE_SOURCE_SHA256:
            raise ValueError('Unknown complete merchant compiler predecessor')
    return value

